"use client";
/* Flick, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Flick(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("flick"); }, []);
  return React.createElement("piix-sprite", { "name": "flick", ...piixAttrs(props) });
}

export default Flick;
